using System; using UnityEngine;
namespace SoulboundLegends.Siege { public enum SiegeDestructibleType{Wall,Gate,Building,Barricade,Tower,Door}; [Serializable] public class SiegeDestructible{public string id;public SiegeDestructibleType type;public float maxHealth=25000,health=25000;public bool destroyed,blocksRoute,requiredToReachCore;} public class SiegeDestructionSystem:MonoBehaviour{public SiegeDestructible[] structures;public event Action<SiegeDestructible> StructureDestroyed;public void DamageStructure(string id,float amount){if(structures==null)return;foreach(var s in structures)if(s.id==id&&!s.destroyed){s.health=Mathf.Max(0,s.health-amount);if(s.health<=0){s.destroyed=true;StructureDestroyed?.Invoke(s);}return;}}} }